(() => {
'use strict';const $=s=>document.querySelector(s),core=window.MixedPractice,key='fondasi-mixed-practice-v1';
const e=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;},math=tex=>{const n=e('span');n.dataset.tex=tex;return n;},link=(href,text)=>{const n=e('a',text);n.href=href;return n;};
let saved=null;try{const v=JSON.parse(localStorage.getItem(key)||'null');if(v&&v.version===1)saved=v;}catch{}
let checked=new Set(Array.isArray(saved?.checked)?saved.checked.filter(id=>core.groups.some(g=>g.id===id)):[]);
for(const group of core.groups){$('#mixed-jumps').append(link('#paket-'+group.id,'Paket '+group.id.toUpperCase()+' · '+group.chapters));const section=$('#paket-'+group.id);section.append(e('h2','Paket '+group.id.toUpperCase()+': '+group.title),e('p',group.chapters+' · Contoh penghubung terpilih, bukan cakupan lengkap seluruh bab.'));const status=e('p');status.id='packet-status-'+group.id;status.className='mixed-status';section.append(status);
for(const q of core.questions.filter(q=>q.group===group.id)){const box=e('div');box.className='mixed-question';box.append(e('h3','Soal '+q.id.slice(1).replace(/^0/,'')));const formula=e('div');formula.className='formula';formula.append(math(q.tex));box.append(formula);if(q.kind==='number'){const label=e('label',q.prompt);label.htmlFor='mixed-answer-'+q.id;const input=e('input');input.type='text';input.id=label.htmlFor;input.maxLength=80;input.autocomplete='off';input.dataset.q=q.id;input.setAttribute('aria-describedby','mixed-feedback-'+q.id);box.append(label,input);}else{const field=e('fieldset');field.append(e('legend',q.prompt));q.options.forEach((tex,i)=>{const label=e('label'),input=e('input');input.type='radio';input.name=q.id;input.value=String(i);input.dataset.q=q.id;label.append(input,math(tex));field.append(label);});box.append(field);}const hint=e('details');hint.append(e('summary','Buka petunjuk'),e('p',q.hint));box.append(hint);const feedback=e('p');feedback.id='mixed-feedback-'+q.id;feedback.className='feedback';feedback.setAttribute('role','status');box.append(feedback);const details=e('details');details.id='mixed-detail-'+q.id;details.hidden=true;const worked=e('div');worked.className='formula worked';worked.append(math(q.worked));details.append(e('summary','Alasan dan bacaan ulang'),e('p',q.why),worked);for(const [href,title]of q.review){const p=e('p');p.append(link(href,title+' →'));details.append(p);}box.append(details);section.append(box);}
const button=e('button','Periksa paket '+group.id.toUpperCase());button.type='submit';button.dataset.group=group.id;button.className='button';section.append(button);const label=e('label','Konsep mana yang perlu diulang, dan langkah apa yang ingin kamu coba?');label.htmlFor='mixed-note-'+group.id;const note=e('textarea');note.id=label.htmlFor;note.rows=3;note.maxLength=3000;note.dataset.note=group.id;note.value=typeof saved?.notes?.[group.id]==='string'?saved.notes[group.id].slice(0,3000):'';section.append(label,note);}
function collect(){const answers={};for(const q of core.questions){answers[q.id]=q.kind==='number'?$('#mixed-answer-'+q.id).value:document.querySelector(`[name="${q.id}"]:checked`)?.value||'';}return core.clean(answers);}
function save(){const notes={};for(const g of core.groups)notes[g.id]=$('#mixed-note-'+g.id).value;try{localStorage.setItem(key,JSON.stringify({version:1,answers:collect(),notes,checked:[...checked]}));$('#mixed-save').textContent='Draf tersimpan di peramban ini. Tidak dikirim ke pengajar.';}catch{$('#mixed-save').textContent='Draf belum dapat disimpan. Salin jawaban dan catatan sebelum meninggalkan halaman.';}}
function render(){const answers=collect(),r=core.assess(answers,[...checked]);$('#mixed-progress').textContent=`${Object.keys(answers).length} dari 12 soal sudah diisi. ${checked.size} dari 4 paket memiliki hasil pemeriksaan terbaru.`;for(const q of core.questions){const status=r.items[q.id],f=$('#mixed-feedback-'+q.id);f.className='feedback '+(status==='correct'?'correct':status==='incorrect'||status==='invalid'?'incorrect':'');f.textContent=status==='unchecked'?'':status==='pending'?'Belum dijawab; tidak dihitung sebagai salah.':status==='invalid'?'Format belum dapat diperiksa. Tulis satu bilangan atau pecahan dengan penyebut bukan nol.':status==='correct'?'Tepat. Buka alasan untuk memeriksa langkahnya.':'Belum tepat. Buka alasan dan pilih bacaan ulang yang sesuai.';$('#mixed-detail-'+q.id).hidden=!['correct','incorrect'].includes(status);}for(const g of core.groups){const states=core.questions.filter(q=>q.group===g.id).map(q=>r.items[q.id]);$('#packet-status-'+g.id).textContent=!checked.has(g.id)?'Belum diperiksa atau jawabannya berubah; periksa paket untuk mendapatkan hasil terbaru.':`${states.filter(s=>s==='correct').length} tepat, ${states.filter(s=>s==='incorrect').length} belum tepat, ${states.filter(s=>s==='invalid').length} perlu perbaikan format, ${states.filter(s=>s==='pending').length} belum dijawab.`;}$('#mixed-results').hidden=checked.size===0;$('#mixed-summary').textContent=`Hasil terbaru: ${r.correct} tepat, ${r.incorrect} belum tepat, ${r.invalid} perlu perbaikan format, ${r.pending} belum dijawab dalam paket yang diperiksa. ${r.unchecked} soal pada paket lain belum diperiksa atau perlu diperiksa ulang.`;const reviews=$('#mixed-reviews');reviews.replaceChildren();if(r.review.length){reviews.append(e('p','Bacaan ulang dari jawaban yang belum tepat:'));for(const [href,title]of r.review)reviews.append(link(href,title+' →'));}else reviews.append(e('p','Belum ada rekomendasi dari jawaban yang diperiksa dan belum tepat. Ini bukan kesimpulan bahwa semua materi sudah dikuasai.'));}
const answers=core.clean(saved?.answers);for(const q of core.questions){if(q.kind==='number')$('#mixed-answer-'+q.id).value=answers[q.id]||'';else if(/^\d+$/.test(answers[q.id]||'')&&Number(answers[q.id])<q.options.length){const radio=document.querySelector(`[name="${q.id}"][value="${Number(answers[q.id])}"]`);if(radio)radio.checked=true;}}
$('#mixed-form').addEventListener('input',event=>{const id=event.target.dataset.q;if(id){const q=core.questions.find(q=>q.id===id);checked.delete(q.group);render();$('#mixed-message').textContent='Jawaban paket '+q.group.toUpperCase()+' berubah. Periksa kembali paket itu untuk memperbarui hasil dan bacaan ulang.';}save();});
$('#mixed-form').addEventListener('keydown',event=>{if(event.key==='Enter'&&event.target.dataset.q&&event.target.type==='text'){event.preventDefault();const q=core.questions.find(q=>q.id===event.target.dataset.q);$('#mixed-form').requestSubmit(document.querySelector('button[data-group="'+q.group+'"]'));}});
$('#mixed-form').addEventListener('submit',event=>{event.preventDefault();const target=event.submitter?.dataset.group,selected=target?[target]:core.groups.map(g=>g.id),answers=collect();if(!core.questions.some(q=>selected.includes(q.group)&&answers[q.id])){$('#mixed-message').textContent='Isi setidaknya satu jawaban dalam paket yang ingin diperiksa. Soal lain boleh dilewati.';return;}for(const id of selected)checked.add(id);render();save();$('#mixed-message').textContent=target?'Paket '+target.toUpperCase()+' sudah diperiksa. Baca tanggapan di bawah setiap soal.':'Jawaban sudah diperiksa. Isian kosong dan format yang belum sah dipisahkan dari jawaban yang belum tepat.';});
$('#mixed-reset').addEventListener('click',()=>{for(const q of core.questions){if(q.kind==='number')$('#mixed-answer-'+q.id).value='';else for(const r of document.querySelectorAll(`[name="${q.id}"]`))r.checked=false;}checked.clear();render();save();$('#mixed-message').textContent='Jawaban dan hasil dikosongkan. Catatan refleksi paket tetap tersedia.';});render();$('#mixed-save').textContent='Draf disimpan di peramban ini bila tersedia.';
})();
